const {{ chromium }} = require('playwright');
(async () => {{
  const browser = await chromium.launch({{ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined }});
  const page = await browser.newPage();
  await page.setViewportSize({{ width: 1920, height: 1080 }});
  await page.goto('http://127.0.0.1:{port}/deck.html', {{ waitUntil: 'networkidle' }});
  await page.waitForTimeout(600);
  for (let i=1; i<=60; i++) {{
    const idx = String(i).padStart(3,'0');
    await page.screenshot({{ path: '{out_dir.as_posix()}/s_' + idx + '.png' }});
    await page.keyboard.press('ArrowRight');
    await page.waitForTimeout(650);
  }}
  await browser.close();
}})();
"""
    script_path.write_text(script)
    env = os.environ.copy()
    env.setdefault('NODE_PATH', '/usr/local/lib/node_modules:/app/node_modules')
    env.setdefault('PLAYWRIGHT_BROWSERS_PATH', '/ms-playwright')
    env.setdefault('PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD', '1')
    subprocess.check_call(['node', str(script_path)], env=env)

    imgs = sorted(out_dir.glob('s_*.png'))
    def sig(path):
        im = Image.open(path)
        w,h = im.size
        pts=[]
        for xf in (0.12,0.33,0.5,0.67,0.88):
            for yf in (0.2,0.5,0.8):
                pts.append(im.getpixel((int(w*xf), int(h*yf))))
        return tuple(pts)

    sigs = [sig(p) for p in imgs]
    # count prefix unique until first repeat (should stop at last slide)
    unique = [imgs[0]]
    for i in range(1, len(imgs)):
        if sigs[i] != sigs[i-1]:
            unique.append(imgs[i])
        else:
            break

    print('unique_prefix', len(unique))

server.shutdown()
